import {BookOpen, ChartNoAxesCombined, FileText, GraduationCap, HeartHandshake, Layers3, Quote, Users} from 'lucide-react';

export function SystemStats(){
 return <section className="panel system-stats" aria-labelledby="system-stats-title"><h2 id="system-stats-title"><Layers3 size={20}/> Thống kê hệ thống</h2><p className="sidebar-note">Chờ kết nối dữ liệu hệ thống.</p><div className="stats-total"><span><Users size={19}/> Thành viên</span><strong aria-label="Chưa có số liệu">—</strong></div><div className="stats-role-list">{[['Học sinh',BookOpen],['Phụ huynh',HeartHandshake],['Giáo viên',GraduationCap]].map(([label,Icon])=>{const Symbol=Icon as typeof Users;return <div key={String(label)}><Symbol size={16}/><span>{String(label)}</span><b aria-label="Chưa có số liệu">—</b></div>})}</div><div className="stats-resource-grid">{[['Đề thi',FileText],['Bài tập',BookOpen]].map(([label,Icon])=>{const Symbol=Icon as typeof Users;return <div key={String(label)}><Symbol size={18}/><strong aria-label="Chưa có số liệu">—</strong><span>{String(label)}</span></div>})}</div><div className="stats-today"><span>Lượt làm bài hôm nay</span><strong aria-label="Chưa có số liệu">—</strong></div><figure className="stats-week"><figcaption><ChartNoAxesCombined size={16}/> Hoạt động 7 ngày</figcaption><div className="stats-chart-placeholder" role="img" aria-label="Biểu đồ 7 ngày đang chờ dữ liệu; chưa có điểm hoặc cột thống kê"><span>Chờ dữ liệu 7 ngày</span></div><div className="stats-chart-days" aria-hidden="true">{['−6','−5','−4','−3','−2','−1','Hôm nay'].map(day=><span key={day}>{day}</span>)}</div></figure><p className="stats-status"><span aria-hidden="true"/> Chưa có số liệu trực tiếp</p></section>;
}

export function TeacherInspiration(){
 return <section className="panel teacher-inspiration" aria-labelledby="inspiration-title"><div className="inspiration-cover"><img src="/assets/toan/footer-v4.webp" alt="Cảnh trường học minh họa"/><span>Hình minh họa</span></div><div className="inspiration-body"><div className="inspiration-avatar"><img src="/assets/toan/educator-v3.webp" alt="Giáo viên minh họa, không phải chân dung cô Nguyễn Thị Diện"/></div><span className="inspiration-portrait-label">Ảnh người minh họa</span><span className="eyebrow">GÓC TRUYỀN CẢM HỨNG</span><h2 id="inspiration-title">Cô Nguyễn Thị Diện</h2><p className="inspiration-role">Đồng hành cùng giáo dục</p><div className="inspiration-quote-placeholder"><Quote size={21} aria-hidden="true"/><p>Lời chia sẻ đang chờ cập nhật.</p></div><p className="inspiration-note">Chờ thông tin giới thiệu được xác nhận. Chưa có chân dung hoặc lời trích dẫn được cung cấp.</p></div></section>;
}
