'use client';
import {useEffect} from 'react';import {seoFor} from '@/lib/seo';
export default function SeoHead({tab,grade,page}:{tab:string;grade:number;page:number}){useEffect(()=>{const seo=seoFor(tab,grade,page);document.title=seo.title;const set=(key:string,content:string,property=false)=>{const attr=property?'property':'name';let el=document.head.querySelector<HTMLMetaElement>(`meta[${attr}="${key}"]`);if(!el){el=document.createElement('meta');el.setAttribute(attr,key);document.head.appendChild(el)}el.content=content};set('description',seo.description);set('robots','noindex, nofollow');set('og:title',seo.title,true);set('og:description',seo.description,true);set('twitter:title',seo.title);set('twitter:description',seo.description)},[tab,grade,page]);return null}
